/* eslint-disable @typescript-eslint/no-explicit-any */
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import '@testing-library/jest-dom'
import { vi, describe, it, beforeEach, expect } from 'vitest'
import { MemoryRouter } from 'react-router-dom'

// Mock api module used by other components
vi.mock('../../api', () => ({
  setPlayerOnline: vi.fn(() => Promise.resolve({ success: true })),
  setPlayerOffline: vi.fn(() => Promise.resolve({ success: true })),
  postPlayerHeartbeat: vi.fn(() => Promise.resolve({ success: true })),
}))

// Mock import.meta.glob for asset imports used by the component
;(global as any).import = { meta: { glob: vi.fn().mockReturnValue({}) } }

import BugCleanupGame from './BugCleanupGame.tsx'

describe('BugCleanupGame basic behaviour', () => {
  beforeEach(() => {
    vi.resetAllMocks()
    localStorage.clear()
    sessionStorage.clear()

    // Provide a simple ResizeObserver mock used by components that query layout
    // (tests in this repo often set this in beforeEach)
    global.ResizeObserver = vi.fn().mockImplementation(() => ({
      observe: vi.fn(),
      unobserve: vi.fn(),
      disconnect: vi.fn()
    })) as any
  })

  it('renders the start modal with age-specific text and a Volgende button', async () => {
    render(
      <MemoryRouter>
        <BugCleanupGame ageGroup={"11-13"} />
      </MemoryRouter>
    )

    expect(screen.getByRole('heading', { name: /Speluitleg - Bug Cleanup/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /Volgende/i })).toBeInTheDocument()
  })

  it('starts the game when clicking Volgende and shows the timer/progress', async () => {
    const { container } = render(
      <MemoryRouter>
        <BugCleanupGame ageGroup={"8-10"} />
      </MemoryRouter>
    )

    const volgende = screen.getByRole('button', { name: /Volgende/i })
    fireEvent.click(volgende)

    // After starting the game the progress bar and timer should be visible
    await waitFor(() => expect(screen.getByRole('progressbar')).toBeInTheDocument())
    expect(container.querySelector('.bc-progress-text')).toBeTruthy()
    expect(container.querySelector('.bc-pill')).toBeTruthy()
  })

  it('opens help modal when global question event is dispatched and shows Verder spelen', async () => {
    render(
      <MemoryRouter>
        <BugCleanupGame ageGroup={"11-13"} />
      </MemoryRouter>
    )

    // ensure intro is present and advance to running state
    fireEvent.click(screen.getByRole('button', { name: /Volgende/i }))

    // open the help overlay via the global event
    window.dispatchEvent(new CustomEvent('minigame:question'))

    const verder = await screen.findByRole('button', { name: /Verder spelen/i })
    expect(verder).toBeInTheDocument()
  })
})

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import './FightTheBug.css'
import '../PasswordZapper/PasswordZapperGame.css'

type AgeGroup = '8-10' | '11-13' | '14-16'
type EndResults = { score: number; timeMs: number; mistakes: number }

interface Props {
  ageGroup?: AgeGroup
  onEnd?: (results: EndResults) => void
}

type Question = {
  id: string
  prompt: string
  options: { id: string; label: string; icon?: string }[]
  correctOptionId: string
  hintLinesByAge?: Partial<Record<AgeGroup, string[]>>
}

function inferAgeGroup(value?: string | null): AgeGroup {
  const raw = String(value || '').toLowerCase()
  try {
    if (/8\D*10/.test(raw)) return '8-10'
    if (/11\D*13/.test(raw)) return '11-13'
    if (/14\D*16/.test(raw)) return '14-16'
    const nums = (raw.match(/\d+/g) || []).map(n => parseInt(n, 10)).filter(n => !Number.isNaN(n))
    if (nums.length >= 1) {
      const n = nums[0]
      if (n <= 10) return '8-10'
      if (n <= 13) return '11-13'
      return '14-16'
    }
    if (raw.includes('8')) return '8-10'
    if (raw.includes('11') || raw.includes('12') || raw.includes('13')) return '11-13'
    if (raw.includes('14') || raw.includes('15') || raw.includes('16')) return '14-16'
  } catch {
    /* fall through */
  }
  return '11-13'
}

